#include "rookforge/board.hpp"
#include "rookforge/search.hpp"
#include "rookforge/notation.hpp"
#include "rookforge/game.hpp"
#include "rookforge/session.hpp"
#include <cstdlib>
#include <iostream>
#include <stdexcept>
using namespace rookforge;
namespace { void require(bool v,const char* m){if(!v)throw std::runtime_error(m);}std::uint64_t perft(Board& b,int d){if(!d)return 1;std::uint64_t n=0;for(auto m:b.legalMoves()){Undo u;b.makeMove(m,u);n+=perft(b,d-1);b.unmakeMove(m,u);}return n;} }
int main(){try{Board b;require(b.legalMoves().size()==20,"initial legal move count");require(perft(b,2)==400,"initial perft 2");require(perft(b,3)==8902,"initial perft 3");require(perft(b,5)==4865609,"initial perft 5");auto original=b.fen();auto m=b.legalMoves().front();Undo u;require(b.makeMove(m,u),"make move");b.unmakeMove(m,u);require(b.fen()==original,"make/unmake restores FEN");require(Board::fromFen(original).fen()==original,"FEN roundtrip");require(san(b,parseUci(b,"e2e4"))=="e4","SAN generation");Board after=b;std::vector<Move> record;for(auto text:{"e2e4","e7e5","g1f3","b8c6"}){auto move=parseUci(after,text);record.push_back(move);Undo step;after.makeMove(move,step);}Board imported;auto importedMoves=importPgn(imported,exportPgn(b,record));require(importedMoves==record,"PGN round trip");Game game;for(int loop=0;loop<2;++loop)for(auto text:{"g1f3","g8f6","f3g1","f6g8"})require(game.play(parseUci(game.board(),text)),"legal game move");require(game.claimThreefold(),"threefold claim");require(game.claimDraw(),"accept valid draw claim");for(int i=0;i<4;++i)require(game.undo(),"game undo");require(game.board().fen()==Board{}.fen(),"undo restores initial position");auto r=search(b,1);require(b.makeMove(r.best,u),"search returned a legal move");auto limited=search(b,8,std::chrono::milliseconds::max(),nullptr,50);require(b.makeMove(limited.best,u),"node-limited search returns a legal fallback");std::atomic_bool cancelled{true};auto stopped=search(b,8,std::chrono::seconds(5),&cancelled);require(b.makeMove(stopped.best,u),"cancelled search returns a legal fallback");Session session;session.startSearch(8,std::chrono::seconds(5));session.restart();require(session.game().board().fen()==Board{}.fen(),"session restart cancels search safely");bool invalid=false;try{Board::fromFen("bad");}catch(const std::invalid_argument&){invalid=true;}require(invalid,"invalid FEN rejected");std::cout<<"All RookForge core tests passed.\n";return EXIT_SUCCESS;}catch(const std::exception& e){std::cerr<<"Test failure: "<<e.what()<<"\n";return EXIT_FAILURE;}}
